const JS="/* Saldo – mobile-first private budget app. Financial data never leaves the browser. */\n'use strict';\nconst FALLBACK = {\"source\":\"Skatteverket SKVFS 2025:20, månadslön, kolumn 1, tabeller 33 och 34; kontrollerade löneintervall 20 001–50 000 kr\",\"year\":2026,\"firstUpper\":20200,\"step\":200,\"tables\":{\"33\":[3439,3488,3537,3585,3634,3682,3731,3780,3828,3877,3925,3974,4023,4071,4120,4170,4220,4270,4320,4371,4421,4471,4521,4572,4622,4672,4722,4773,4823,4873,4923,4974,5024,5074,5124,5175,5225,5275,5325,5376,5426,5476,5526,5577,5627,5677,5727,5778,5828,5878,5928,5979,6029,6079,6129,6180,6230,6280,6330,6381,6431,6481,6531,6582,6632,6682,6732,6783,6833,6883,6933,6984,7034,7084,7134,7185,7235,7285,7335,7386,7436,7486,7536,7587,7637,7687,7737,7788,7838,7888,7938,7989,8039,8089,8139,8189,8239,8289,8339,8402,8468,8534,8600,8666,8732,8798,8864,8930,8996,9062,9128,9194,9260,9326,9392,9458,9524,9590,9656,9722,9788,9854,9920,9986,10052,10118,10184,10250,10316,10382,10448,10514,10580,10646,10712,10778,10844,10910,10976,11042,11108,11174,11240,11306,11372,11438,11504,11570,11636,11702],\"34\":[3541,3591,3642,3692,3742,3792,3842,3892,3942,3992,4042,4092,4142,4193,4243,4294,4346,4398,4449,4501,4553,4605,4656,4708,4760,4812,4863,4915,4967,5019,5070,5122,5174,5226,5277,5329,5381,5433,5484,5536,5588,5639,5691,5743,5795,5847,5898,5950,6002,6054,6105,6157,6209,6261,6312,6364,6416,6467,6519,6571,6623,6674,6726,6778,6830,6881,6933,6985,7037,7088,7140,7192,7244,7295,7347,7399,7451,7502,7554,7606,7658,7709,7761,7813,7865,7916,7968,8020,8072,8123,8175,8227,8279,8330,8382,8433,8485,8536,8588,8652,8720,8788,8856,8924,8992,9060,9128,9196,9264,9332,9400,9468,9536,9604,9672,9740,9808,9876,9944,10012,10080,10148,10216,10284,10352,10420,10488,10556,10624,10692,10760,10828,10896,10964,11032,11100,11168,11236,11304,11372,11440,11508,11576,11644,11712,11780,11848,11916,11984,12052]}};\nconst STORE_KEY='saldo-private-v1';\nconst MONTHS=['januari','februari','mars','april','maj','juni','juli','augusti','september','oktober','november','december'];\nconst SHORT=['jan','feb','mar','apr','maj','jun','jul','aug','sep','okt','nov','dec'];\nconst TAX_SOURCE_URL='https://www.skatteverket.se/foretag/arbetsgivare/arbetsgivaravgifterochskatteavdrag/skattetabeller';\nconst CATEGORIES={\n  'Mat & dryck':{emoji:'🥑',color:'#b6f1a1'},\n  'Boende':{emoji:'🏠',color:'#91bcff'},\n  'Transport':{emoji:'🚙',color:'#f4ca83'},\n  'Shopping':{emoji:'🛍️',color:'#cfb3ff'},\n  'Abonnemang':{emoji:'📱',color:'#7bded2'},\n  'Nöje':{emoji:'🎬',color:'#edb3ac'},\n  'Hälsa':{emoji:'💊',color:'#a5d3fe'},\n  'Övrigt':{emoji:'🧾',color:'#9eabb7'}\n};\nconst curFmt=new Intl.NumberFormat('sv-SE',{maximumFractionDigits:0});\nconst money=n=>curFmt.format(Math.round(Number(n)||0))+' kr';\nconst compact=n=>curFmt.format(Math.round(Number(n)||0));\nconst e=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,8);\nconst now=new Date();\nconst initialMonth=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`;\nconst fallbackRows={};\nfor(const [table,values] of Object.entries(FALLBACK.tables))fallbackRows[table]=values.map((tax,i)=>[20001+i*200,20200+i*200,tax,0]);\nfunction defaultData(){return {version:1,settings:{gross:0,table:'33',manualTax:null,savingsGoal:10000,startingSavings:0},months:{},recurring:[],savings:{opening:0,startMonth:initialMonth,initialized:false,transactions:[]},viewMonth:initialMonth};}\nfunction normalizeSavings(s){const d={opening:0,startMonth:initialMonth,initialized:false,transactions:[]};if(!s||typeof s!=='object')return d;const transactions=Array.isArray(s.transactions)?s.transactions.filter(x=>x&&validMonth(x.month)&&['in','out'].includes(x.type)&&Number.isFinite(Number(x.amount))&&Number(x.amount)>0).map(x=>({id:String(x.id||uid()),type:x.type,month:x.month,amount:Math.round(Number(x.amount)*100)/100,label:String(x.label||'').slice(0,80),added:Number(x.added)||0})):[];return {opening:Number.isFinite(Number(s.opening))?Math.max(0,Math.round(Number(s.opening))):0,startMonth:validMonth(s.startMonth)?s.startMonth:initialMonth,initialized:!!s.initialized||transactions.length>0,transactions};}\nfunction load(){try {const s=JSON.parse(localStorage.getItem(STORE_KEY));if(!s||s.version!==1)return defaultData();const z=defaultData();return {...z,...s,settings:{...z.settings,...s.settings},months:s.months&&typeof s.months==='object'?s.months:{},recurring:Array.isArray(s.recurring)?s.recurring:[],savings:normalizeSavings(s.savings)};}catch{return defaultData();}}\nlet state=load();\nlet taxTables={33:fallbackRows[33],34:fallbackRows[34]};\nlet taxSource='lokal';\nlet activeFilter='alla';\nlet deferredInstallPrompt=null;\nlet toastTimer;\nlet modalOpen=false;\nfunction save(){try{localStorage.setItem(STORE_KEY,JSON.stringify(state));}catch{toast('Kunde inte spara. Kontrollera webbläsarens lagringsutrymme.');}}\nfunction toast(str){const old=document.querySelector('.toast');if(old)old.remove();const t=document.createElement('div');t.className='toast';t.textContent=str;document.body.append(t);clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.remove(),3600);}\nfunction validMonth(m){return /^\\d{4}-(0[1-9]|1[0-2])$/.test(m)}\nfunction shiftMonth(m,diff){const [year,month]=m.split('-').map(Number);const dt=new Date(year,month-1+diff,1);return `${dt.getFullYear()}-${String(dt.getMonth()+1).padStart(2,'0')}`;}\nfunction monthTitle(m){const [year,month]=m.split('-').map(Number);return MONTHS[month-1][0].toUpperCase()+MONTHS[month-1].slice(1)+' '+year;}\nfunction monthState(m){if(!state.months[m])state.months[m]={expenses:[],grossOverride:null};return state.months[m];}\nfunction calcTax(gross,table,manual){const g=Math.round(Number(gross)||0);if(g<=0)return {tax:0,source:'ingen'};\n if(manual!==null&&manual!==''&&Number.isFinite(Number(manual)))return {tax:Math.min(g,Math.max(0,Math.round(Number(manual)))),source:'egen'};\n const rows=taxTables[String(table)]||[];let min=0,max=rows.length-1;while(min<=max){const mid=Math.floor((min+max)/2);const row=rows[mid];if(g<row[0])max=mid-1;else if(g>row[1])min=mid+1;else return {tax:row[3]?Math.round(g*row[2]/100):row[2],source:taxSource,bracket:[row[0],row[1]]};}\n return {tax:null,source:'saknas'};\n}\nfunction getEntries(m){const one=state.months[m]?.expenses||[];return [...one.map(x=>({...x,recurring:false})),...state.recurring.map(x=>({...x,recurring:true}))].sort((a,b)=>b.added-a.added);}\nfunction monthlySavings(m){const tx=state.savings.transactions.filter(x=>x.month===m).sort((a,b)=>b.added-a.added);const deposits=tx.filter(x=>x.type==='in').reduce((sum,x)=>sum+x.amount,0);const withdrawals=tx.filter(x=>x.type==='out').reduce((sum,x)=>sum+x.amount,0);return {tx,deposits,withdrawals,net:deposits-withdrawals};}\nfunction savingsBalance(m){const s=state.savings;if(!s.initialized)return 0;if(m<s.startMonth)return null;let sum=s.opening;for(const x of s.transactions)if(x.month>=s.startMonth&&x.month<=m)sum+=x.type==='in'?x.amount:-x.amount;return sum;}\nfunction calc(m){const gross=state.months[m]?.grossOverride??state.settings.gross;\n const taxRes=calcTax(gross,state.settings.table,state.settings.manualTax);\n const net=taxRes.tax===null?null:gross-taxRes.tax;\n const entries=getEntries(m),spend=entries.reduce((x,y)=>x+Number(y.amount||0),0);\n const saving=monthlySavings(m);return {gross,tax:taxRes.tax,source:taxRes.source,net,spend,saving,remain:net===null?null:net-spend-saving.net,entries};\n}\nfunction categories(entries){const result={};for(const tx of entries){result[tx.category]=(result[tx.category]||0)+Number(tx.amount||0)}return Object.entries(result).sort((a,b)=>b[1]-a[1]);}\nfunction guessCategory(label){const s=label.toLocaleLowerCase('sv-SE');if(/foodora|wolt|pizza|restaurang|ica|willys|coop|lidl|hemköp|mat |lunch|middag/.test(s))return 'Mat & dryck';if(/hyra|avgift|bolån|ränta|el |elektricitet|vatten|boende|bredband|garage/.test(s))return 'Boende';if(/bensin|diesel|mack|parkering|fordon|bil |bilskatt|taxi|uber|buss|tåg|pendling/.test(s))return 'Transport';if(/netflix|spotify|viaplay|youtube|abonnemang|telefon|mobil|hbo|disney/.test(s))return 'Abonnemang';if(/bio|konsert|spel|film|nöje/.test(s))return 'Nöje';if(/apotek|läkare|vård|gym|hälsa/.test(s))return 'Hälsa';if(/kläder|amazon|shopping|ikea|elgiganten/.test(s))return 'Shopping';return 'Övrigt';}\nfunction taxNote(m){const year=Number(m.slice(0,4));if(year!==2026)return 'Obs! Skatten för '+year+' är en prognos med 2026 års tabell. Den är inte en fastställd skatteberäkning för '+year+'.';return ''}\nconst iconSvg=(type,size=21)=>({\n menu:'<path d=\"M4 7h16M4 12h16M4 17h16\"/>',\n plus:'<path d=\"M12 5v14M5 12h14\"/>',\n arrow:'<path d=\"M5 12h14m-6-6 6 6-6 6\"/>',\n settings:'<path d=\"M12 3v3m0 12v3M3 12h3m12 0h3M5.6 5.6l2.1 2.1m8.6 8.6 2.1 2.1m0-12.8-2.1 2.1m-8.6 8.6-2.1 2.1\"/><circle cx=\"12\" cy=\"12\" r=\"4\"/>',\n chevronLeft:'<path d=\"m15 18-6-6 6-6\"/>',chevronRight:'<path d=\"m9 18 6-6-6-6\"/>',\n shield:'<path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z\"/><path d=\"m9 12 2 2 4-4\"/>',\n trash:'<path d=\"M4 7h16M10 11v6m4-6v6M6 7l1 13h10l1-13M9 7V4h6v3\"/>',\n edit:'<path d=\"M12 20h9M16 4a2.1 2.1 0 0 1 3 3L8 18l-4 1 1-4L16 4Z\"/>',\n close:'<path d=\"M6 6l12 12M18 6L6 18\"/>',\n download:'<path d=\"M12 3v12m-4-4 4 4 4-4M5 17v4h14v-4\"/>',\n up:'<path d=\"m4 17 6-6 4 3 6-8\"/>',\n wallet:'<path d=\"M3 7a2 2 0 0 1 2-2h14v14H5a2 2 0 0 1-2-2V7Zm0 1h16v4H3\"/><circle cx=\"16\" cy=\"14\" r=\"1\"/>',\n alert:'<circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M12 8v5m0 4h.01\"/>',\n check:'<path d=\"m4 12 5 5L20 6\"/>'\n}[type]||'');\nfunction ico(name,size=21){return `<svg viewBox=\"0 0 24 24\" width=\"${size}\" height=\"${size}\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">${iconSvg(name,size)}</svg>`}\nfunction metric(title,amount,desc,symbol,style=''){return `<article class=\"metric\"><div class=\"metricTitle\"><span>${title}</span><span class=\"metricIcon\">${symbol}</span></div><div class=\"metricValue\" style=\"${style}\">${amount===null?'—':compact(amount)}<span style=\"font-size:.43em;letter-spacing:0;color:var(--muted)\"> kr</span></div><div class=\"metricFooter\">${desc}</div></article>`;}\nfunction rowHtml(tx){const cat=CATEGORIES[tx.category]||CATEGORIES['Övrigt'];return `<div class=\"tx\"><div class=\"txIcon\">${cat.emoji}</div><div class=\"txText\"><div class=\"txName\">${e(tx.label)}</div><div class=\"txMeta\">${e(tx.category)}${tx.recurring?' · Återkommande':''}</div></div><div class=\"txAmount\">−${money(tx.amount)}</div><div class=\"txActions\"><button class=\"editTx\" data-id=\"${e(tx.id)}\" data-rec=\"${tx.recurring}\" title=\"Ändra utgift\" aria-label=\"Ändra ${e(tx.label)}\">${ico('edit',16)}</button><button class=\"delTx\" data-id=\"${e(tx.id)}\" data-rec=\"${tx.recurring}\" title=\"Ta bort utgift\" aria-label=\"Ta bort ${e(tx.label)}\">${ico('trash',16)}</button></div></div>`;}\nfunction renderRows(entries){const filtered=activeFilter==='återkommande'?entries.filter(x=>x.recurring):entries;\nif(!filtered.length)return `<div class=\"empty\"><div class=\"emptyIcon\">🧾</div><div class=\"emptyTitle\">${activeFilter==='återkommande'?'Inga återkommande utgifter än':'Inga utgifter inlagda ännu'}</div><div class=\"emptyText\">Skriv till exempel <b>Foodora -2500</b> ovan, så räknar vi av beloppet direkt från nettolönen.</div></div>`;\nreturn filtered.map(rowHtml).join('');}\nfunction renderDonut(entries,total){const cat=categories(entries);if(!cat.length)return '<div class=\"empty\" style=\"padding:20px\"><div class=\"emptyIcon\">◉</div><div class=\"emptyTitle\">Din fördelning dyker upp här</div><div class=\"emptyText\">Lägg till en utgift för att se vart pengarna går.</div></div>';\nlet pos=0;const stops=cat.map(([k,v])=>{const p=100*v/total;const color=(CATEGORIES[k]||CATEGORIES['Övrigt']).color;const seg=`${color} ${pos}% ${pos+p}%`;pos+=p;return seg;}).join(',');\nreturn `<div class=\"split\"><div class=\"donut\" style=\"background:conic-gradient(${stops})\"><div class=\"donutInner\"><strong>${compact(total)}</strong><span>kr utgifter</span></div></div><div>${cat.slice(0,6).map(([k,v])=>`<div class=\"catRow\"><span class=\"catDot\" style=\"background:${CATEGORIES[k]?.color||'#9eabb7'}\"></span><span class=\"catName\">${e(k)}</span><span class=\"catSum\">${compact(v)} kr</span></div>`).join('')}</div></div>`;\n}\nfunction renderYear(m){const yr=Number(m.split('-')[0]);const months=MONTHS.map((_,i)=>`${yr}-${String(i+1).padStart(2,'0')}`);const calcs=months.map(calc);const totalNet=calcs.reduce((a,x)=>a+(x.net||0),0);const totalExp=calcs.reduce((a,x)=>a+x.spend,0);const totalSavings=calcs.reduce((a,x)=>a+x.saving.net,0);const totalRem=calcs.every(x=>x.remain!==null)?totalNet-totalExp-totalSavings:null;\nconst maxVal=Math.max(1,...calcs.map(x=>Math.abs(x.remain||0)));return `<section class=\"panel yearPanel\"><div class=\"panelPad\"><div class=\"panelHead\"><div><div class=\"panelTitle\">Årsöversikt <span class=\"muted\" style=\"font-weight:500\">${yr}</span></div><div class=\"panelSub\">Beräknat utifrån lön, utgifter och överföringar till sparande</div></div></div><div class=\"yearStats\"><div class=\"yearStat\"><span>Netto, beräknat</span><strong>${money(totalNet)}</strong></div><div class=\"yearStat\"><span>Utgifter</span><strong>${money(totalExp)}</strong></div><div class=\"yearStat\"><span>Till sparande, netto</span><strong>${money(totalSavings)}</strong></div><div class=\"yearStat\"><span>Möjligt kvar</span><strong class=\"${totalRem!==null&&totalRem<0?'red':''}\">${totalRem===null?'—':money(totalRem)}</strong></div></div><div class=\"bars\">${calcs.map((x,i)=>{const val=x.remain??0;const h=Math.max(3,Math.abs(val)/maxVal*99);const title=SHORT[i]+': '+(x.remain===null?'skatt saknas':money(x.remain));return `<div class=\"barCol ${months[i]===m?'selected':''}\" data-month=\"${months[i]}\" title=\"${e(title)}\" tabindex=\"0\" role=\"button\" aria-label=\"Öppna ${MONTHS[i]} ${yr}\"><div class=\"barArea\"><div class=\"bar ${val<0?'negative':''}\" style=\"height:${h}%\"></div></div><span class=\"barMonth\">${SHORT[i]}</span></div>`}).join('')}</div><div class=\"sectionHint\">Årsöversikten visar beräknade pengar kvar efter utgifter och registrerade sparöverföringar. Sparkapitalet ovan är ett separat registrerat saldo, inte en prognos. Månader utan utgifter kan se bättre ut än verkligheten. ${yr!==2026?'Skatten använder fortfarande 2026 års tabeller.':''}</div></div></section>`;}\nfunction savingsRow(tx){const adding=tx.type==='in';return `<div class=\"savingTx\"><div class=\"savingTxIcon ${adding?'':'withdraw'}\">${adding?'↗':'↙'}</div><div class=\"savingTxBody\"><strong>${e(tx.label|| (adding?'Insättning':'Uttag'))}</strong><span>${adding?'Insättning till sparande':'Uttag från sparande'} · ${monthTitle(tx.month)}</span></div><strong class=\"savingTxAmount ${adding?'positive':'red'}\">${adding?'+':'−'}${money(tx.amount)}</strong><button class=\"txActions savingsDelete\" data-id=\"${e(tx.id)}\" aria-label=\"Ta bort sparhändelse\" title=\"Ta bort\">${ico('trash',17)}</button></div>`;}\nfunction renderSavings(m){const x=monthlySavings(m),balance=savingsBalance(m),s=state.savings;const canShow=balance!==null;\nreturn `<section class=\"savingsPanel\" id=\"savingsPanel\"><div class=\"savingsHeader\"><div><div class=\"savingsEyebrow\">✦ DITT SPARANDE</div><div class=\"savingsHeading\">Sparkapital</div><div class=\"savingsValue\">${canShow?compact(balance):'—'} <span>kr</span></div><div class=\"savingsSummary\">${!s.initialized?'Börja med att ange hur mycket du redan har sparat.':canShow?`Startsaldo ${money(s.opening)} · från ${monthTitle(s.startMonth)}`:`Sparandet börjar ${monthTitle(s.startMonth)}`}</div></div><div class=\"savingsIcon\">${ico('up',30)}</div></div>\n<div class=\"savingsFacts\"><div><span>Insatt denna månad</span><strong class=\"positive\">+${money(x.deposits)}</strong></div><div><span>Uttaget denna månad</span><strong>${x.withdrawals?'−':''}${money(x.withdrawals)}</strong></div></div>\n<div class=\"savingsButtons\"><button class=\"primary\" id=\"addSaving\">${ico('plus',17)} Lägg till sparande</button><button class=\"secondary\" id=\"setSavingsStart\">${ico('edit',16)} ${s.initialized?'Ändra startsaldo':'Ange startsaldo'}</button></div>\n<div class=\"savingsHistory\"><div class=\"savingsHistoryHead\"><strong>Händelser ${monthTitle(m)}</strong><span>${x.tx.length} ${x.tx.length===1?'post':'poster'}</span></div>${x.tx.length?x.tx.map(savingsRow).join(''):'<p class=\"savingsEmpty\">Inga insättningar eller uttag denna månad ännu.</p>'}</div>\n<p class=\"savingsFootnote\">Sparande är <b>inte en utgift</b>. En insättning minskar ändå ”Kvar att använda” eftersom pengarna flyttas från månadens budget till ditt sparande. Uttag gör tvärtom. Saldo hämtar inga kontouppgifter från banken.</p></section>`;}\nfunction openSavingsStart(){const s=state.savings,reference=s.initialized?s.startMonth:state.viewMonth;modal(`${formIntro(s.initialized?'Ändra startsparandet':'Ditt startsparande','Hur mycket pengar hade du sparat från början?')}<form id=\"savingsStartForm\"><label class=\"field\"><span>Startsaldo (kr)</span><input id=\"openingSavings\" type=\"number\" inputmode=\"decimal\" step=\"1\" min=\"0\" max=\"1000000000\" required placeholder=\"200000\" value=\"${s.initialized?s.opening:''}\"></label><div class=\"notice\">Det här beloppet är ditt sparande <b>i början av ${monthTitle(reference)}</b>. Sparinsättningar och uttag läggs sedan ovanpå. Uppgiften sparas bara på den här enheten.</div><div class=\"modalFooter\"><button class=\"secondary closeModal\" type=\"button\">Avbryt</button><button class=\"primary\" type=\"submit\">Spara startsaldo</button></div></form>`);\ndocument.getElementById('savingsStartForm').onsubmit=ev=>{ev.preventDefault();const amount=Number(document.getElementById('openingSavings').value);if(!Number.isFinite(amount)||amount<0||amount>1000000000){toast('Ange ett giltigt startsaldo.');return;}s.opening=Math.round(amount);if(!s.initialized){const first=s.transactions.reduce((acc,x)=>x.month<acc?x.month:acc,state.viewMonth);s.startMonth=first;}s.initialized=true;save();closeModal();render();toast('Startsaldot är sparat!');};document.getElementById('openingSavings').focus();}\nfunction openSavingTransaction(){modal(`${formIntro('Överföring till sparande',`Registrera en händelse i ${monthTitle(state.viewMonth)}.`)}<form id=\"savingTxForm\"><label class=\"field\"><span>Typ av överföring</span><select id=\"savingsType\"><option value=\"in\">Insättning – ökar sparandet</option><option value=\"out\">Uttag – minskar sparandet</option></select></label><label class=\"field\"><span>Belopp (kr)</span><input id=\"savingsAmount\" type=\"number\" min=\"1\" max=\"1000000000\" step=\"1\" inputmode=\"numeric\" required placeholder=\"10000\"></label><label class=\"field\"><span>Anteckning (valfri)</span><input id=\"savingsLabel\" maxlength=\"80\" placeholder=\"T.ex. Sparat från novemberlönen\"></label><div class=\"notice\">Insättningar redovisas separat från vanliga utgifter men dras av från ”Kvar att använda” denna månad.</div><div class=\"modalFooter\"><button type=\"button\" class=\"secondary closeModal\">Avbryt</button><button class=\"primary\" type=\"submit\">Spara överföring</button></div></form>`);\ndocument.getElementById('savingTxForm').onsubmit=ev=>{ev.preventDefault();const amount=Number(document.getElementById('savingsAmount').value),type=document.getElementById('savingsType').value,label=document.getElementById('savingsLabel').value.trim();if(!Number.isFinite(amount)||amount<=0||amount>1000000000){toast('Ange ett giltigt belopp.');return;}const s=state.savings;if(!s.initialized){s.initialized=true;s.startMonth=state.viewMonth;s.opening=0;}if(state.viewMonth<s.startMonth)s.startMonth=state.viewMonth;const curr=savingsBalance(state.viewMonth);if(type==='out'&&amount>curr){toast('Uttaget kan inte vara större än sparkapitalet för månaden.');return;}s.transactions.push({id:uid(),type,month:state.viewMonth,amount:Math.round(amount),label:label.slice(0,80),added:Date.now()});save();closeModal();render();toast(type==='in'?'Sparandet har ökat!':'Uttaget har registrerats');};document.getElementById('savingsAmount').focus();}\nfunction deleteSaving(id){const s=state.savings,tx=s.transactions.find(x=>x.id===id);if(!tx)return;if(!confirm('Ta bort denna '+(tx.type==='in'?'insättning':'uttag')+' på '+money(tx.amount)+'?'))return;s.transactions=s.transactions.filter(x=>x.id!==id);save();render();toast('Sparhändelsen borttagen');}\nfunction installed(){return window.matchMedia('(display-mode: standalone)').matches||window.navigator.standalone===true;}\nfunction render(){const m=validMonth(state.viewMonth)?state.viewMonth:initialMonth;state.viewMonth=m;const data=calc(m),hasIncome=data.gross>0;\nconst budgetUsed=data.spend+data.saving.net;const spentPercent=data.net&&data.net>0?Math.max(0,Math.min(100,budgetUsed/data.net*100)):0;\nconst estimate=taxNote(m);const installButton=installed()?'':`<button class=\"ghost\" id=\"installBtn\" type=\"button\">Installera app</button>`;\nconst remainingLabel=data.remain===null?'—':compact(data.remain);\nconst taxBadge=data.source==='egen'?'Eget skatteavdrag':`Skattetabell ${state.settings.table} · kolumn 1`;\nconst heroMsg=!hasIncome?'Börja med att ange din bruttolön. Sedan räknas allt automatiskt.':data.tax===null?'Skatteuppgift saknas för denna lön. Ange faktiskt skatteavdrag eller försök igen när Skatteverkets tabell laddats.':data.remain>=0?`Du har ${money(data.remain)} kvar efter utgifter och sparöverföringar den här månaden.`:`Utgifter och överföringar till sparande överstiger nettolönen med ${money(-data.remain)}.`;\ndocument.querySelector('#app').innerHTML=`<div class=\"shell\">\n<header class=\"topbar\"><a href=\"/\" class=\"brand\" aria-label=\"Saldo startsida\"><div class=\"mark\">${ico('up',26)}</div><div><div class=\"brandname\">saldo<span style=\"color:var(--accent)\">.</span></div><div class=\"brandtag\">Din privata ekonomi</div></div></a><div class=\"actions\">${installButton}<button class=\"icon-btn\" id=\"settingsBtn\" aria-label=\"Inställningar\" title=\"Inställningar\">${ico('settings',23)}</button></div></header>\n<div class=\"subtop\"><div><div class=\"eyebrow\">DIN MÅNADSÖVERSIKT</div><h1 class=\"h1\">Pengar med full kontroll.</h1></div><div class=\"month-select\"><button id=\"prevMonth\" aria-label=\"Föregående månad\">${ico('chevronLeft')}</button><div class=\"current\">${monthTitle(m)}</div><button id=\"nextMonth\" aria-label=\"Nästa månad\">${ico('chevronRight')}</button></div></div>\n${!hasIncome?`<div class=\"banner\"><span style=\"font-size:24px\">✨</span><div><strong>Välkommen till Saldo!</strong>Fyll i din bruttolön och välj skattetabell. Sedan kan du lägga till utgifter som dras från din beräknade nettolön.<br><button class=\"inlineLink\" id=\"startIncome\">Ställ in min lön →</button></div></div>`:''}\n<section class=\"hero\"><div class=\"heroTop\"><span class=\"chip\"><span class=\"chipDot\"></span>${data.remain!==null&&data.remain<0?'Över budget':'Din ekonomi i realtid'}</span><span class=\"muted tiny\">${e(taxBadge)}</span></div><div class=\"heroLabel\">Kvar att använda</div><div class=\"heroValue ${data.remain!==null&&data.remain<0?'negative':''}\">${remainingLabel} <span class=\"currency\">kr</span></div><div class=\"heroMsg\">${e(heroMsg)}</div><div class=\"progress ${data.net!==null&&budgetUsed>data.net?'over':''}\"><div style=\"width:${spentPercent}%\"></div></div><div class=\"heroFoot\"><span>${data.net===null?'Skatt behöver kontrolleras':`Utgifter: ${money(data.spend)} · Sparat: ${money(data.saving.net)}`}</span><span>${data.net>0?`${Math.round(spentPercent)} % av nettolönen fördelat`:'Din överblick börjar här'}</span></div></section>\n<div class=\"metricGrid\">${metric('Bruttolön',data.gross,'<button id=\"editIncome\" class=\"inlineLink\">Ändra lön →</button>','↗')}${metric('Skatteavdrag',data.tax,'Enligt Skatteverket 2026','⌁')}${metric('Nettolön',data.net,'Efter preliminär skatt','✓')}${metric('Utgifter',data.spend,`${data.entries.length} registrerade poster`,'↘')}</div>\n${renderSavings(m)}\n<div class=\"layout\"><div>\n<section class=\"panel\"><div class=\"panelPad\"><div class=\"panelHead\"><div><div class=\"panelTitle\">Dina utgifter</div><div class=\"panelSub\">Lägg in allt från Foodora till fasta räkningar</div></div><button class=\"secondary\" id=\"newExpense\" aria-label=\"Ny utgift\">${ico('plus',15)} <span>Ny</span></button></div>\n<form class=\"quick\" id=\"quickForm\"><input id=\"quickInput\" autocomplete=\"off\" placeholder=\"Foodora -2500\" aria-label=\"Snabbregistrera en utgift, exempel Foodora minus 2500\" required><button class=\"primary small\" type=\"submit\">Lägg till</button></form>\n<div class=\"quickHelp\">Skriv <b>Foodora -2500</b> eller <b>Diesel -1800</b>. Beloppet dras automatiskt från nettolönen.</div>\n<div class=\"toolbar\"><div class=\"filters\"><button data-filter=\"alla\" class=\"${activeFilter==='alla'?'active':''}\">Alla (${data.entries.length})</button><button data-filter=\"återkommande\" class=\"${activeFilter==='återkommande'?'active':''}\">Återkommande</button></div><span class=\"muted tiny\">${monthTitle(m)}</span></div><div id=\"txList\">${renderRows(data.entries)}</div></div></section>\n${renderYear(m)}\n</div><div>\n<section class=\"panel\"><div class=\"panelPad\"><div class=\"panelHead\"><div><div class=\"panelTitle\">Så fördelas pengarna</div><div class=\"panelSub\">Utgifter efter kategori</div></div></div>${renderDonut(data.entries,data.spend)}</div></section>\n<section class=\"panel\" style=\"margin-top:20px\"><div class=\"panelPad\"><div class=\"panelHead\"><div><div class=\"panelTitle\">Din löneuträkning</div><div class=\"panelSub\">Köping · preliminär skatt 2026</div></div><button class=\"quiet\" id=\"taxSettings\">Ändra</button></div>\n<div class=\"saldoRow\"><span class=\"netName\">Bruttolön</span><strong>${money(data.gross)}</strong></div><div class=\"saldoRow\"><span class=\"netName\">Skatt · tabell ${e(state.settings.table)}</span><strong class=\"red\">${data.tax===null?'Saknas':'−'+money(data.tax)}</strong></div><div class=\"saldoRow\"><span class=\"netName\">Nettolön</span><strong class=\"positive\">${data.net===null?'—':money(data.net)}</strong></div><div class=\"saldoRow\"><span class=\"netName\">Registrerade utgifter</span><strong class=\"red\">−${money(data.spend)}</strong></div><div class=\"saldoRow\"><span class=\"netName\">Till sparande, netto</span><strong>${data.saving.net>=0?\"−\":\"+\"}${money(Math.abs(data.saving.net))}</strong></div><div class=\"saldoRow\"><strong>Kvar att använda</strong><strong style=\"font-size:18px\" class=\"${data.remain!==null&&data.remain<0?'red':'positive'}\">${data.remain===null?'—':money(data.remain)}</strong></div>\n<div class=\"taxStatus ${estimate||data.tax===null?'warn':''}\">${estimate?e(estimate):data.tax===null?'Skatteverkets fullständiga tabell kunde inte läsas. För lön utanför vårt kontrollerade offlineintervall kan du ange det faktiska skatteavdraget under inställningar.':`Skatteberäkningen använder ${data.source==='egen'?'ditt eget skattebelopp':data.source==='officiell'?'Skatteverkets publicerade månadstabell 2026':'ett kontrollerat utdrag ur Skatteverkets 2026-tabell'} (kolumn 1).`}</div><div class=\"helper\">Gäller vanlig månadslön som huvudinkomst för person under 66 år. Bonus, jämkning, förmåner och andra inkomster kan ändra faktiskt skatteavdrag. <a href=\"${TAX_SOURCE_URL}\" target=\"_blank\" rel=\"noopener\">Se Skatteverkets tabeller ↗</a></div>\n</div></section>\n<section class=\"panel\" style=\"margin-top:20px\"><div class=\"panelPad\"><div class=\"panelHead\"><div><div class=\"panelTitle\">Dina uppgifter</div><div class=\"panelSub\">Bara sparade i denna webbläsare</div></div></div><div style=\"display:grid;grid-template-columns:1fr 1fr;gap:9px\"><button class=\"secondary\" id=\"exportBtn\">${ico('download',16)} Säkerhetskopia</button><button class=\"secondary\" id=\"importBtn\">Importera</button></div><p class=\"helper\">Saldo har ingen inloggning och skickar inte dina inkomster eller utgifter till servern. Exportera gärna en backup om du byter telefon.</p><input type=\"file\" id=\"importFile\" accept=\"application/json,.json\" class=\"hidden\"></div></section>\n</div></div>\n<div class=\"footer\"><span>saldo. © 2026 · Gjord för enkel vardagsekonomi</span><span>Skatteunderlag: Skatteverket 2026 · Köping <span style=\"color:var(--accent)\">v1.1</span></span></div></div><div id=\"modalHost\"></div>`;\nwire();}\nfunction wire(){document.getElementById('prevMonth').onclick=()=>setView(shiftMonth(state.viewMonth,-1));document.getElementById('nextMonth').onclick=()=>setView(shiftMonth(state.viewMonth,1));\ndocument.getElementById('settingsBtn').onclick=openSettings;document.getElementById('taxSettings').onclick=openSettings;\nconst income=document.getElementById('editIncome');if(income)income.onclick=openIncome;const start=document.getElementById('startIncome');if(start)start.onclick=openIncome;\ndocument.getElementById('newExpense').onclick=()=>openExpense();\ndocument.getElementById('setSavingsStart').onclick=openSavingsStart;document.getElementById('addSaving').onclick=openSavingTransaction;document.querySelectorAll('.savingsDelete').forEach(btn=>btn.onclick=()=>deleteSaving(btn.dataset.id));\ndocument.getElementById('quickForm').onsubmit=ev=>{ev.preventDefault();const raw=document.getElementById('quickInput').value.trim();const match=raw.match(/^(.+?)\\s*[-−]\\s*([\\d\\s.,]+)\\s*(?:kr)?$/i);if(!match){toast('Skriv exempelvis Foodora -2500');return;}let amount=parseMoney(match[2]);if(!Number.isFinite(amount)||amount<=0){toast('Ange ett giltigt belopp större än noll.');return;}addExpense({label:match[1].trim(),amount,category:guessCategory(match[1]),added:Date.now()},false);toast('Utgiften är registrerad!');};\ndocument.querySelectorAll('[data-filter]').forEach(btn=>btn.onclick=()=>{activeFilter=btn.dataset.filter;render();});document.querySelectorAll('.editTx').forEach(btn=>btn.onclick=()=>{const tx=findExpense(btn.dataset.id,btn.dataset.rec==='true');if(tx)openExpense(tx,btn.dataset.rec==='true');});document.querySelectorAll('.delTx').forEach(btn=>btn.onclick=()=>deleteExpense(btn.dataset.id,btn.dataset.rec==='true'));\ndocument.querySelectorAll('.barCol').forEach(bar=>{bar.onclick=()=>setView(bar.dataset.month);bar.onkeydown=ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();setView(bar.dataset.month)}}});\ndocument.getElementById('exportBtn').onclick=exportData;document.getElementById('importBtn').onclick=()=>document.getElementById('importFile').click();document.getElementById('importFile').onchange=importData;\nconst b=document.getElementById('installBtn');if(b)b.onclick=installApp;\n}\nfunction setView(m){state.viewMonth=m;save();render();}\nfunction parseMoney(v){const text=String(v).replace(/\\s|kr/gi,'').replace(',','.');if(/\\d+\\.\\d{3}$/.test(text))return Number(text.replace('.',''));return Number(text);}\nfunction addExpense(x,repeat){const entry={id:uid(),label:x.label.trim().slice(0,100),amount:Math.round(Number(x.amount)*100)/100,category:x.category||'Övrigt',added:Date.now()};if(!entry.label||entry.amount<=0)return;if(repeat)state.recurring.push(entry);else monthState(state.viewMonth).expenses.push(entry);save();render();}\nfunction findExpense(id,repeat){return (repeat?state.recurring:state.months[state.viewMonth]?.expenses||[]).find(x=>x.id===id);}\nfunction deleteExpense(id,repeat){const x=findExpense(id,repeat);if(!x)return;if(!confirm(`Ta bort ”${x.label}”${repeat?' från alla månader':''}?`))return;const list=repeat?state.recurring:monthState(state.viewMonth).expenses;const i=list.findIndex(x=>x.id===id);if(i!==-1)list.splice(i,1);save();render();toast('Utgiften borttagen');}\nfunction modal(html){modalOpen=true;document.querySelector('#modalHost').innerHTML=`<div class=\"modalOverlay\" id=\"modalOverlay\"><div class=\"modal\" role=\"dialog\" aria-modal=\"true\">${html}</div></div>`;const overlay=document.getElementById('modalOverlay');overlay.onclick=ev=>{if(ev.target===overlay)closeModal();};document.querySelectorAll('.closeModal').forEach(x=>x.onclick=closeModal);document.addEventListener('keydown',onEsc);}\nfunction onEsc(ev){if(ev.key==='Escape'&&modalOpen)closeModal();}\nfunction closeModal(){modalOpen=false;const host=document.getElementById('modalHost');if(host)host.innerHTML='';document.removeEventListener('keydown',onEsc);}\nfunction formIntro(title,subtitle){return `<div class=\"modalHeader\"><div><div class=\"modalTitle\">${title}</div><div class=\"modalSub\">${subtitle}</div></div><button class=\"icon-btn closeModal\" aria-label=\"Stäng\">${ico('close')}</button></div>`;}\nfunction openExpense(item=null,recurring=false){const isEdit=!!item;const value=item?.amount||'';const category=item?.category||'Övrigt';modal(`${formIntro(isEdit?'Ändra utgift':'Ny utgift','Registrera köp eller fasta kostnader för din ekonomi.')}<form id=\"expenseForm\"><label class=\"field\"><span>Vad gäller utgiften?</span><input id=\"expenseName\" maxlength=\"100\" required placeholder=\"Exempel: Foodora\" value=\"${e(item?.label||'')}\"></label><div class=\"grid2\"><label class=\"field\"><span>Belopp (kr)</span><input id=\"expenseAmount\" type=\"number\" min=\"0.01\" step=\"0.01\" required inputmode=\"decimal\" placeholder=\"2500\" value=\"${e(value)}\"></label><label class=\"field\"><span>Kategori</span><select id=\"expenseCategory\">${Object.keys(CATEGORIES).map(k=>`<option ${k===category?'selected':''}>${e(k)}</option>`).join('')}</select></label></div><label class=\"inlineCheck\"><input type=\"checkbox\" id=\"expenseRecurring\" ${recurring?'checked':''}><span>Återkommande utgift varje månad, t.ex. hyra, försäkring eller abonnemang</span></label><div class=\"modalFooter\"><button class=\"secondary closeModal\" type=\"button\">Avbryt</button><button class=\"primary\" type=\"submit\">${isEdit?'Spara ändring':'Lägg till utgift'}</button></div></form>`);\nconst name=document.getElementById('expenseName'),cat=document.getElementById('expenseCategory');if(!isEdit)name.onblur=()=>{if(cat.value==='Övrigt')cat.value=guessCategory(name.value);};\ndocument.getElementById('expenseForm').onsubmit=ev=>{ev.preventDefault();const label=name.value.trim(),amount=Number(document.getElementById('expenseAmount').value),category=cat.value,newRecurring=document.getElementById('expenseRecurring').checked;\n if(!label||!Number.isFinite(amount)||amount<=0){toast('Kontrollera beloppet och beskrivningen.');return;}\n if(isEdit){const oldList=recurring?state.recurring:monthState(state.viewMonth).expenses;const oldIdx=oldList.findIndex(x=>x.id===item.id);if(oldIdx!==-1)oldList.splice(oldIdx,1);const tx={...item,label,amount,category};(newRecurring?state.recurring:monthState(state.viewMonth).expenses).push(tx);save();render();toast('Utgiften har ändrats');}else{addExpense({label,amount,category},newRecurring);toast('Utgiften har lagts till');}closeModal();};name.focus();}\nfunction openIncome(){const override=state.months[state.viewMonth]?.grossOverride;modal(`${formIntro('Din månadslön','Vi använder bruttolönen för att räkna fram nettolönen.')}<form id=\"incomeForm\"><label class=\"field\"><span>Bruttolön per månad (kr)</span><input id=\"grossInput\" type=\"number\" min=\"0\" max=\"2000000\" step=\"1\" inputmode=\"numeric\" value=\"${override??state.settings.gross}\" required></label><label class=\"inlineCheck\"><input type=\"checkbox\" id=\"oneMonthOnly\" ${override!==null&&override!==undefined?'checked':''}><span>Gäller bara ${monthTitle(state.viewMonth)} (t.ex. extra arbetstid eller en annan lön)</span></label><div class=\"notice\">Din nettolön beräknas med Skatteverkets skattetabell ${e(state.settings.table)}, kolumn 1, för Köping. Du kan ändra tabellen under inställningar.</div><div class=\"modalFooter\"><button type=\"button\" class=\"secondary closeModal\">Avbryt</button><button type=\"submit\" class=\"primary\">Spara min lön</button></div></form>`);\ndocument.getElementById('incomeForm').onsubmit=ev=>{ev.preventDefault();const val=Number(document.getElementById('grossInput').value);if(!Number.isFinite(val)||val<0||val>2000000){toast('Ange en giltig bruttolön.');return;}if(document.getElementById('oneMonthOnly').checked){monthState(state.viewMonth).grossOverride=Math.round(val);}else{state.settings.gross=Math.round(val);monthState(state.viewMonth).grossOverride=null;}save();render();closeModal();toast('Lönen har uppdaterats');};document.getElementById('grossInput').focus();}\nfunction openSettings(){modal(`${formIntro('Skatt & inställningar','Anpassad för kommun Köping, inkomståret 2026.')}<form id=\"settingsForm\"><label class=\"field\"><span>Skattetabell för din A-skattsedel</span><select id=\"tableInput\"><option value=\"33\" ${state.settings.table==='33'?'selected':''}>Tabell 33 – utan kyrkoavgift</option><option value=\"34\" ${state.settings.table==='34'?'selected':''}>Tabell 34 – normalt med kyrkoavgift</option></select></label><div class=\"notice\">Köping har totalt cirka 33,33 % skatte- och begravningsavgift utan kyrkoavgift (2026), vilket ger tabell 33. Med kyrkoavgift blir det vanligtvis tabell 34. Kontrollera alltid din A-skattsedel eller lönebesked för att bekräfta exakt tabell.</div><label class=\"inlineCheck\"><input type=\"checkbox\" id=\"useManual\" ${state.settings.manualTax!==null?'checked':''}><span>Jag vill ange mitt faktiska skatteavdrag från lönebeskedet i stället</span></label><label class=\"field\" id=\"manualField\" style=\"${state.settings.manualTax===null?'display:none':''}\"><span>Faktiskt skatteavdrag per månad (kr)</span><input id=\"manualInput\" inputmode=\"numeric\" min=\"0\" step=\"1\" type=\"number\" value=\"${state.settings.manualTax??0}\"></label><p class=\"helper\">Stöder vanlig månadslön som huvudinkomst för den som inte fyllde 66 år vid 2026 års början (kolumn 1). Justera med faktiskt skatteavdrag om du har jämkning, bonus, förmåner eller andra förhållanden.</p><div class=\"modalFooter\"><button class=\"secondary closeModal\" type=\"button\">Avbryt</button><button class=\"primary\" type=\"submit\">Spara inställningar</button></div></form><div class=\"helper\" style=\"margin-top:16px\">Källa: <a href=\"${TAX_SOURCE_URL}\" target=\"_blank\" rel=\"noopener\">Skatteverket – skattetabeller 2026</a>.</div>`);\ndocument.getElementById('useManual').onchange=ev=>{document.getElementById('manualField').style.display=ev.target.checked?'block':'none';};document.getElementById('settingsForm').onsubmit=ev=>{ev.preventDefault();state.settings.table=document.getElementById('tableInput').value;const checked=document.getElementById('useManual').checked;const v=Number(document.getElementById('manualInput').value);if(checked&&(!Number.isFinite(v)||v<0)){toast('Ange ett giltigt skattebelopp.');return;}state.settings.manualTax=checked?Math.round(v):null;save();render();closeModal();toast('Skatteinställningarna sparade');};}\nfunction exportData(){const copy=JSON.stringify(state,null,2);const blob=new Blob([copy],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='saldo-backup-'+new Date().toISOString().slice(0,10)+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('Säkerhetskopia exporterad');}\nasync function importData(ev){const f=ev.target.files?.[0];if(!f)return;try{if(f.size>2_000_000)throw new Error('Filen är för stor.');const incoming=JSON.parse(await f.text());if(!incoming||incoming.version!==1||!incoming.settings||!incoming.months||!Array.isArray(incoming.recurring))throw new Error('Felaktig backupfil.');if(!confirm('Det här ersätter den ekonomi du sparat på den här enheten. Fortsätta?'))return;state={...defaultData(),...incoming,settings:{...defaultData().settings,...incoming.settings},savings:normalizeSavings(incoming.savings)};save();render();toast('Din säkerhetskopia har importerats');}catch(error){toast('Importen misslyckades: '+error.message);}finally{ev.target.value='';}}\nasync function installApp(){if(installed()){toast('Appen är redan installerad');return;}if(deferredInstallPrompt){const prompt=deferredInstallPrompt;deferredInstallPrompt=null;prompt.prompt();try{await prompt.userChoice;}catch{}return;}\nmodal(`${formIntro('Installera Saldo','Få en ikon på hemskärmen och öppna utan webbläsarens adressfält.')}<div class=\"notice\">På Android: öppna sidan i <b>Chrome</b>, tryck på menyknappen ⋮ och välj <b>Installera app</b> eller <b>Lägg till på startskärmen</b>. Om det redan finns en ikon kan den vara installerad.</div><div class=\"modalFooter\"><button class=\"primary closeModal\">Okej</button></div>`);}\nasync function loadTaxTables(){try{const response=await fetch('/api/tables',{cache:'no-store'});if(!response.ok)throw new Error('Tax unavailable');const result=await response.json();if(result.year!==2026)throw new Error('Wrong tax year');if(result.tables&&Array.isArray(result.tables['33'])&&Array.isArray(result.tables['34'])&&result.tables['33'].length>30&&result.tables['34'].length>30){taxTables=result.tables;taxSource=result.source==='official'?'officiell':'lokal';render();}}catch{taxSource='lokal';render();}}\nwindow.addEventListener('beforeinstallprompt',ev=>{ev.preventDefault();deferredInstallPrompt=ev;});window.addEventListener('appinstalled',()=>{deferredInstallPrompt=null;render();toast('Saldo har installerats!');});\nif('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));\nrender();loadTaxTables();\n";
