const SW="const CACHE = 'saldo-pwa-2026-v2';\nconst ASSETS=['/','/app.css','/app.js','/icon-192.png','/icon-512.png','/manifest.webmanifest'];\nself.addEventListener('install',event=>{event.waitUntil((async()=>{const cache=await caches.open(CACHE);await cache.addAll(ASSETS);self.skipWaiting();})());});\nself.addEventListener('activate',event=>{event.waitUntil((async()=>{const keys=await caches.keys();await Promise.all(keys.filter(x=>x!==CACHE).map(x=>caches.delete(x)));await self.clients.claim();})());});\nself.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(url.origin!==self.location.origin||event.request.method!=='GET')return;\nif(url.pathname.startsWith('/api/')){event.respondWith(fetch(event.request).catch(()=>new Response(JSON.stringify({error:'offline'}),{headers:{'Content-Type':'application/json'},status:503})));return;}\nevent.respondWith((async()=>{const cache=await caches.open(CACHE);try{const fresh=await fetch(event.request);if(fresh.ok)cache.put(event.request,fresh.clone());return fresh;}catch{return await cache.match(event.request)||await cache.match('/')||new Response('Offline', {status:503});}})());});\n";
